  const DICOS = { fr: FR, en: EN, es: ES };
  const detecter = () => {
    try {
      if (window.__pcvLangueTest) return window.__pcvLangueTest;
      let l = "";
      try {
        l = (window.opener?.LocalizationManager || window.LocalizationManager)?.m_rgLocalesToUse?.[0] || "";
      } catch (e) {
      }
      l = (l || document.documentElement.lang || navigator.language || "fr").toLowerCase();
      return l.startsWith("fr") ? "fr" : l.startsWith("es") ? "es" : "en";
    } catch (e) {
      return "fr";
    }
  };
  window.__pcvT = (cle, vars) => {
    const d = DICOS[detecter()] || FR;
    let texte = d[cle] ?? EN[cle] ?? cle;
    if (vars) for (const k in vars) texte = texte.split("{" + k + "}").join(vars[k]);
    return texte;
  };
  const LOCALES = { fr: "fr-FR", en: "en-US", es: "es-ES" };
  window.__pcvLangue = detecter;
  window.__pcvLocale = () => LOCALES[detecter()] || "fr-FR";
  const poserTxtCss = () => {
    try {
      const V = {
        "--pcv-txt-aucun-telech": window.__pcvT("css.aucun_telechargement"),
        "--pcv-txt-alimentation": window.__pcvT("home.alimentation"),
        "--pcv-txt-en-ligne": window.__pcvT("home.en_ligne"),
        "--pcv-txt-mediatheque": window.__pcvT("place.mediatheque"),
        "--pcv-txt-choisir-jeu": window.__pcvT("css.choisir_jeu"),
        "--pcv-txt-filtrer": window.__pcvT("css.filtrer"),
        "--pcv-txt-boutique": window.__pcvT("spaces.boutique.nom"),
        "--pcv-txt-amis-discussions": window.__pcvT("css.amis_discussions"),
        "--pcv-txt-continuer": window.__pcvT("home.reprendre"),
        "--pcv-txt-reglages-rapides": window.__pcvT("acces.titre"),
        "--pcv-txt-notifications": window.__pcvT("spaces.notifs.nom"),
        "--pcv-txt-amis": window.__pcvT("spaces.amis.nom"),
        "--pcv-txt-performances": window.__pcvT("acces.performances"),
        "--pcv-txt-musique": window.__pcvT("acces.musique"),
        "--pcv-txt-aide": window.__pcvT("acces.aide"),
        "--pcv-txt-luminosite": window.__pcvT("acces.luminosite"),
        "--pcv-txt-desactive": window.__pcvT("acces.desactive"),
        "--pcv-txt-active": window.__pcvT("acces.active"),
        "--pcv-txt-volume": window.__pcvT("acces.volume"),
        "--pcv-txt-micro": window.__pcvT("acces.micro"),
        "--pcv-txt-mode-avion": window.__pcvT("acces.mode_avion"),
        "--pcv-txt-connecte": window.__pcvT("acces.connecte_statut")
      };
      for (const k in V) document.documentElement.style.setProperty(k, JSON.stringify(V[k]));
    } catch (e) {
    }
  };
  poserTxtCss();
